-- EventMesh schema.
-- Conventions: UUIDv7 primary keys generated by the application, timestamptz
-- everywhere, enum-like columns as text with CHECK constraints, a foreign key
-- on every reference.

CREATE TABLE users (
    id            uuid PRIMARY KEY,
    email         text        NOT NULL,
    password_hash text        NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    -- The application trims and lowercases the email before storing it; this
    -- constraint guarantees it, so the plain unique index below is
    -- effectively case-insensitive.
    CONSTRAINT users_email_normalized CHECK (email = lower(btrim(email)) AND email <> '')
);
CREATE UNIQUE INDEX users_email_key ON users (email);

CREATE TABLE sessions (
    id           uuid PRIMARY KEY,
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash   bytea       NOT NULL,
    expires_at   timestamptz NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now()
);
-- Session lookup on every authenticated request.
CREATE UNIQUE INDEX sessions_token_hash_key ON sessions (token_hash);
-- "End all other sessions" on password change.
CREATE INDEX sessions_user_id_idx ON sessions (user_id);

CREATE TABLE api_keys (
    id           uuid PRIMARY KEY,
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name         text        NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
    key_prefix   text        NOT NULL,
    key_hash     bytea       NOT NULL,
    last_used_at timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now(),
    revoked_at   timestamptz
);
-- Key lookup on every ingestion request.
CREATE UNIQUE INDEX api_keys_key_hash_key ON api_keys (key_hash);
-- Key list on the dashboard.
CREATE INDEX api_keys_user_id_created_at_idx ON api_keys (user_id, created_at DESC);

CREATE TABLE webhook_endpoints (
    id                     uuid PRIMARY KEY,
    user_id                uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name                   text        NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
    url                    text        NOT NULL CHECK (char_length(url) BETWEEN 1 AND 2048),
    event_types            text[]      NOT NULL CHECK (cardinality(event_types) BETWEEN 1 AND 50),
    secret_ciphertext      bytea       NOT NULL,
    enabled                boolean     NOT NULL DEFAULT true,
    rate_limit_per_second  integer     NOT NULL DEFAULT 10 CHECK (rate_limit_per_second BETWEEN 1 AND 1000),
    -- NULL means "use the system default" for the three retry settings.
    max_retries            integer     CHECK (max_retries BETWEEN 0 AND 20),
    initial_retry_delay_ms integer     CHECK (initial_retry_delay_ms BETWEEN 100 AND 3600000),
    max_retry_delay_ms     integer     CHECK (max_retry_delay_ms BETWEEN 100 AND 86400000),
    deleted_at             timestamptz,
    created_at             timestamptz NOT NULL DEFAULT now(),
    updated_at             timestamptz NOT NULL DEFAULT now()
);
-- Endpoint list, and the "active endpoints of this user" read during ingestion.
CREATE INDEX webhook_endpoints_user_active_idx ON webhook_endpoints (user_id, created_at DESC)
    WHERE deleted_at IS NULL;

CREATE TABLE events (
    id              uuid PRIMARY KEY,
    user_id         uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    event_type      text        NOT NULL CHECK (char_length(event_type) BETWEEN 1 AND 100),
    payload         jsonb       NOT NULL CHECK (jsonb_typeof(payload) = 'object'),
    idempotency_key text        CHECK (char_length(idempotency_key) BETWEEN 1 AND 255),
    request_hash    bytea       NOT NULL,
    created_at      timestamptz NOT NULL DEFAULT now()
);
-- Idempotency: correctness rests on this constraint, not on a read-then-write check.
CREATE UNIQUE INDEX events_user_idempotency_key ON events (user_id, idempotency_key)
    WHERE idempotency_key IS NOT NULL;
-- Keyset-paginated event history.
CREATE INDEX events_user_created_idx ON events (user_id, created_at DESC, id DESC);
-- Event history filtered by type.
CREATE INDEX events_user_type_created_idx ON events (user_id, event_type, created_at DESC);

CREATE TABLE deliveries (
    id                   uuid PRIMARY KEY,
    event_id             uuid        NOT NULL REFERENCES events (id) ON DELETE CASCADE,
    endpoint_id          uuid        NOT NULL REFERENCES webhook_endpoints (id),
    -- Denormalized on purpose: ownership checks and list queries need no join.
    user_id              uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    status               text        NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'processing', 'retry_scheduled', 'delivered', 'dead_letter', 'cancelled')),
    -- Every HTTP attempt ever recorded; equals the number of delivery_attempts rows.
    attempt_count        integer     NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    -- Attempts since the last manual replay; this is what the retry limit is compared against.
    cycle_attempt_count  integer     NOT NULL DEFAULT 0 CHECK (cycle_attempt_count >= 0),
    replay_count         integer     NOT NULL DEFAULT 0 CHECK (replay_count >= 0),
    next_attempt_at      timestamptz NOT NULL DEFAULT now(),
    lease_expires_at     timestamptz,
    locked_by            text,
    last_attempt_at      timestamptz,
    last_response_status integer,
    last_error_category  text,
    last_error           text,
    created_at           timestamptz NOT NULL DEFAULT now(),
    updated_at           timestamptz NOT NULL DEFAULT now(),
    -- One delivery per (event, endpoint). Replay resets this row instead of adding one.
    CONSTRAINT deliveries_event_endpoint_key UNIQUE (event_id, endpoint_id),
    -- A row is leased exactly when it is being processed.
    CONSTRAINT deliveries_lease_matches_status CHECK (
        (status = 'processing') = (lease_expires_at IS NOT NULL AND locked_by IS NOT NULL)
    )
);
-- Delivery explorer: list by owner, optionally by status, newest first.
CREATE INDEX deliveries_user_status_created_idx ON deliveries (user_id, status, created_at DESC);
-- Delivery explorer without a status filter (keyset pagination).
CREATE INDEX deliveries_user_created_idx ON deliveries (user_id, created_at DESC, id DESC);
-- Endpoint detail: that endpoint's delivery history.
CREATE INDEX deliveries_endpoint_created_idx ON deliveries (endpoint_id, created_at DESC);
-- Reconciler: deliveries that are due. Partial, so it stays small: terminal rows are not in it.
CREATE INDEX deliveries_due_idx ON deliveries (next_attempt_at)
    WHERE status IN ('pending', 'retry_scheduled');
-- Reaper: leases that have expired.
CREATE INDEX deliveries_lease_idx ON deliveries (lease_expires_at)
    WHERE status = 'processing';
-- Note: "deliveries (event_id)" for event detail is served by the unique
-- constraint's index on (event_id, endpoint_id); a second index would be redundant.

CREATE TABLE delivery_attempts (
    id                    uuid PRIMARY KEY,
    delivery_id           uuid        NOT NULL REFERENCES deliveries (id) ON DELETE CASCADE,
    attempt_number        integer     NOT NULL CHECK (attempt_number >= 1),
    "trigger"             text        NOT NULL CHECK ("trigger" IN ('initial', 'retry', 'replay')),
    worker_id             text        NOT NULL,
    started_at            timestamptz NOT NULL,
    response_status       integer,
    response_body_excerpt text        CHECK (octet_length(response_body_excerpt) <= 2048),
    duration_ms           integer     NOT NULL CHECK (duration_ms >= 0),
    error_category        text,
    error_message         text,
    created_at            timestamptz NOT NULL DEFAULT now(),
    -- Also the index for "attempts of a delivery, in order".
    CONSTRAINT delivery_attempts_delivery_number_key UNIQUE (delivery_id, attempt_number)
);

CREATE TABLE audit_logs (
    id            uuid PRIMARY KEY,
    user_id       uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    action        text        NOT NULL,
    resource_type text        NOT NULL,
    resource_id   uuid,
    metadata      jsonb       NOT NULL DEFAULT '{}'::jsonb,
    created_at    timestamptz NOT NULL DEFAULT now()
);
-- Activity page, keyset-paginated.
CREATE INDEX audit_logs_user_created_idx ON audit_logs (user_id, created_at DESC, id DESC);
